package glitch

import data.glitch_lib

verify_attrs := {"validate_certs", "verify", "verify_mode", "verify_peer", "gpgcheck", "ssl_verify", "insecure", "inspec_verify", "tls_verify", "strict_host_key_checking", "host_key_checking"}

check_attrs := {"checksum", "digest", "sha256", "md5", "hash", "integrity", "signature", "gpg_key", "gpgcakey"}

disabled_values := {"false", "no", "0", "off", "disable", "disabled", "none", "null", "skip", "bypass"}

check_disabled(val) {
    val.ir_type == "Boolean"
    val.value == false
} else {
    val.ir_type == "Integer"
    val.value == 0
} else {
    val.ir_type == "String"
    glitch_lib.contains(val.value, disabled_values[_])
} else {
    val.ir_type == "Null"
}

has_disabled_verify(attrs) {
    attr := attrs[_]
    attr.name == verify_attrs[_]
    check_disabled(attr.value)
}

has_missing_check(attrs) {
    attr := attrs[_]
    attr.name == check_attrs[_]
    check_disabled(attr.value)
}

has_no_integrity_check(attrs) {
    not has_integrity_present(attrs)
}

has_integrity_present(attrs) {
    attr := attrs[_]
    attr.name == check_attrs[_]
    not check_disabled(attr.value)
}

