package glitch

import data.glitch_lib

disabled_values := {"false", "no", "0", "off", "disable", "disabled", "none", "null", "skip", "bypass", "ignore", "never"}

url_attrs := {"url", "source", "src", "baseurl", "mirrorlist", "repo_url", "repository", "download_url", "uri", "location"}

# Attributes that enable/disable integrity/verification when set to false
verify_disable_attrs := {"validate_certs", "verify", "gpgcheck", "ssl_verify", "tls_verify", "strict_host_key_checking", "host_key_checking", "check_signature", "use_gpg", "verify_ssl", "use_masterballs", "key_bundle_trust_chain_validation", "chef_rest_validators", "verify_peer", "insecure"}

# Attributes that flag integrity check disabled when present and true
insecure_flag_attrs := {"insecure", "skip_verify", "disable_verify", "no_checksum", "insecure_pull"}

# Integrity mechanism attributes that should be present for remote downloads
integrity_attrs := {"checksum", "digest", "sha256", "md5", "hash", "integrity", "signature", "sha1", "sha512", "gpgkey", "key_url", "checksum_sha256", "checksum_md5", "remote_checksum", "validate_task", "props_checksum"}

is_disabled_value(val) {
    val.ir_type == "Boolean"
    val.value == false
} else {
    val.ir_type == "Integer"
    val.value == 0
} else {
    val.ir_type == "String"
    lower(val.value) == disabled_values[_]
}

is_remote_url_attr(name) {
    lower(name) == url_attrs[_]
}

is_verify_disable_attr(name) {
    lower(name) == verify_disable_attrs[_]
}

is_insecure_flag_attr(name) {
    lower(name) == insecure_flag_attrs[_]
}

is_integrity_attr(name) {
    contains(lower(name), integrity_attrs[_])
}

has_remote_source(node) {
    walk(node, [_, attr])
    attr.ir_type == "Attribute"
    is_remote_url_attr(attr.name)
    not is_local_url(attr.value)
}

is_local_url(val) {
    val.ir_type == "String"
    startswith(lower(val.value), "file://")
} else {
    val.ir_type == "String"
    startswith(lower(val.value), "/")
}

has_integrity_mechanism(node) {
    walk(node, [_, attr])
    attr.ir_type == "Attribute"
    is_integrity_attr(attr.name)
    not is_null_or_undef(attr.value)
}

has_enabled_verification(node) {
    walk(node, [_, attr])
    attr.ir_type == "Attribute"
    is_verify_disable_attr(attr.name)
    not is_disabled_value(attr.value)
}

is_null_or_undef(val) {
    val.ir_type == "Null"
} else {
    val.ir_type == "Undef"
}

# Detect disabled verification attributes
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    walk(parent, [_, attr])
    attr.ir_type == "Attribute"
    is_verify_disable_attr(attr.name)
    is_disabled_value(attr.value)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing Support for Integrity Check - Verification mechanism disabled. (CWE-353)"
    }
}

# Detect insecure flag attributes set to true
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    walk(parent, [_, attr])
    attr.ir_type == "Attribute"
    is_insecure_flag_attr(attr.name)
    attr.value.ir_type == "Boolean"
    attr.value.value == true

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing Support for Integrity Check - Insecure flag enabled, bypassing integrity checks. (CWE-353)"
    }
}

# Detect missing integrity for remote downloads in atomic units
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    atomic_units := glitch_lib.all_atomic_units(parent)
    au := atomic_units[_]

    has_remote_source(au)
    not has_integrity_mechanism(au)
    not has_enabled_verification(au)

    result := {
        "type": "sec_no_int_check",
        "element": au,
        "path": parent.path,
        "description": "Missing Support for Integrity Check - Resource fetching remote content without integrity verification mechanism. (CWE-353)"
    }
}

# Detect gpgcheck=0 in Hash values (common in yum repository definitions)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    vars := glitch_lib.all_variables(parent)
    v := vars[_]

    has_gpgcheck_disabled(v.value)
    kv := get_gpgcheck_kv(v.value)

    result := {
        "type": "sec_no_int_check",
        "element": kv,
        "path": parent.path,
        "description": "Missing Support for Integrity Check - GPG signature verification disabled (gpgcheck=0). (CWE-353)"
    }
}

has_gpgcheck_disabled(val) {
    walk(val, [_, kv])
    kv.ir_type == "KeyValue"
    lower(kv.key.value) == "gpgcheck"
    is_disabled_value(kv.value)
}

get_gpgcheck_kv(val) = kv {
    walk(val, [_, kv])
    kv.ir_type == "KeyValue"
    lower(kv.key.value) == "gpgcheck"
    is_disabled_value(kv.value)
    kv
}

